  updated_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  UNIQUE(scope, scope_id, proxy_id),
  FOREIGN KEY (proxy_id) REFERENCES proxy_registry(id) ON DELETE RESTRICT
);

--TABLE:quota_allocations
CREATE TABLE IF NOT EXISTS quota_allocations (
  pool_id TEXT NOT NULL REFERENCES quota_pools(id) ON DELETE CASCADE,
  api_key_id TEXT NOT NULL,
  weight DOUBLE PRECISION NOT NULL CHECK (weight >= 0 AND weight <= 100),
  cap_value DOUBLE PRECISION,
  cap_unit TEXT CHECK (cap_unit IN ('percent','requests','tokens','usd')),
  policy TEXT NOT NULL CHECK (policy IN ('hard','soft','burst')) DEFAULT 'hard',
  PRIMARY KEY (pool_id, api_key_id)
);

--TABLE:relay_logs
CREATE TABLE IF NOT EXISTS relay_logs (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  token_id TEXT NOT NULL,
  request_id TEXT,
  model TEXT,
  prompt_tokens BIGINT DEFAULT 0,
  completion_tokens BIGINT DEFAULT 0,
  cost DOUBLE PRECISION DEFAULT 0,
  status TEXT DEFAULT 'success',
  status_code BIGINT DEFAULT 200,
  latency_ms BIGINT DEFAULT 0,
  client_ip TEXT,
  user_agent TEXT,
  created_at BIGINT NOT NULL,
  FOREIGN KEY (token_id) REFERENCES relay_tokens(id) ON DELETE CASCADE
);

--TABLE:relay_rate_limits
CREATE TABLE IF NOT EXISTS relay_rate_limits (
  token_id TEXT NOT NULL,
  window_start BIGINT NOT NULL,
  request_count BIGINT DEFAULT 0,
  cost DOUBLE PRECISION DEFAULT 0,
  PRIMARY KEY (token_id, window_start),
  FOREIGN KEY (token_id) REFERENCES relay_tokens(id) ON DELETE CASCADE
);

--TABLE:skill_agent_grants
CREATE TABLE IF NOT EXISTS skill_agent_grants (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  agent_id TEXT NOT NULL,
  collection_id TEXT NOT NULL REFERENCES skill_collections(id) ON DELETE CASCADE,
  permission TEXT NOT NULL DEFAULT 'discover',
  granted_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  UNIQUE (agent_id, collection_id, permission)
);

--TABLE:skill_collection_members
CREATE TABLE IF NOT EXISTS skill_collection_members (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  collection_id TEXT NOT NULL REFERENCES skill_collections(id) ON DELETE CASCADE,
  skill_id TEXT NOT NULL,
  added_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  UNIQUE (collection_id, skill_id)
);

--TABLE:skill_executions
CREATE TABLE IF NOT EXISTS skill_executions (
  id TEXT PRIMARY KEY,
  skill_id TEXT NOT NULL,
  api_key_id TEXT NOT NULL,
  session_id TEXT,
  input TEXT NOT NULL,
  output TEXT,
  status TEXT NOT NULL CHECK (status IN ('pending', 'running', 'success', 'error', 'timeout')),
  error_message TEXT,
  duration_ms BIGINT,
  created_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  FOREIGN KEY (skill_id) REFERENCES skills(id) ON DELETE CASCADE
);

--TABLE:skill_packages
CREATE TABLE IF NOT EXISTS skill_packages (
  id TEXT PRIMARY KEY,
  source_id TEXT NOT NULL REFERENCES skill_sources(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  domain TEXT,
  description TEXT,
  revision TEXT,
  tags TEXT,
  license TEXT,
  executable BIGINT NOT NULL DEFAULT 0,
  quarantine BIGINT NOT NULL DEFAULT 0,
  quarantine_reasons TEXT,
  status TEXT NOT NULL DEFAULT 'active',
  imported_at TEXT,
  updated_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
);

--TABLE:webhook_deliveries
CREATE TABLE IF NOT EXISTS webhook_deliveries (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  webhook_id TEXT NOT NULL,
  event_type TEXT NOT NULL,
  status TEXT NOT NULL,
  http_status BIGINT,
  latency_ms BIGINT,
  error TEXT,
  payload_snapshot TEXT,
  created_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  FOREIGN KEY (webhook_id) REFERENCES webhooks(id) ON DELETE CASCADE
);

--TABLE:batch_item_checkpoints
CREATE TABLE IF NOT EXISTS batch_item_checkpoints (
  batch_id TEXT NOT NULL,
  line_number BIGINT NOT NULL,
  custom_id TEXT,
  status TEXT NOT NULL CHECK (status IN ('pending', 'processing', 'completed', 'errored')),
  result_json TEXT,
  error_json TEXT,
  created_at BIGINT NOT NULL,
  updated_at BIGINT NOT NULL,
  PRIMARY KEY (batch_id, line_number),
  FOREIGN KEY(batch_id) REFERENCES batches(id) ON DELETE CASCADE
);

--TABLE:skill_package_files
CREATE TABLE IF NOT EXISTS skill_package_files (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  package_id TEXT NOT NULL REFERENCES skill_packages(id) ON DELETE CASCADE,
  path TEXT NOT NULL,
  size BIGINT,
  sha256 TEXT,
  scan_flags TEXT
);

-- ── Special-case replacements ──

-- ── FTS5 replacement: memory_fts → tsvector on memories ──
-- Live FTS5 indexed (content, key) from the external-content table
-- `memories`. PG equivalent: generated tsvector + GIN index.
ALTER TABLE memories ADD COLUMN IF NOT EXISTS search_tsv tsvector GENERATED ALWAYS AS (to_tsvector('english', coalesce(content, '') || ' ' || coalesce(key, ''))) STORED;
CREATE INDEX IF NOT EXISTS memory_fts_idx ON memories USING gin(search_tsv);

-- ── vec0 replacement: vec_memories → pgvector ──
-- vec0 keyed embeddings by the memories rowid (memory_id BIGINT).
CREATE TABLE IF NOT EXISTS vec_memories (
  id BIGINT PRIMARY KEY,
  embedding vector(1024)
);
-- HNSW index only if the vector extension build supports it; commented
-- out by default because PG 18 hnsw requires a distance operator class.
-- CREATE INDEX IF NOT EXISTS vec_memories_hnsw ON vec_memories USING hnsw(id);

