CREATE OR REPLACE FUNCTION trg_provider_connections_retire_chatgpt_web_insert_fn() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  UPDATE provider_connections
    SET is_active = 0,
        test_status = 'unavailable',
        error_code = 'PROVIDER_REMOVED',
        last_error = 'Provider integration retired from OmniRoute v3.8.51',
        last_error_type = 'provider_removed',
        last_error_source = 'migration:retire-chatgpt-web',
        last_error_at = to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
        updated_at = to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
    WHERE id = NEW.id
      AND (
        is_active IS DISTINCT FROM 0
        OR test_status IS DISTINCT FROM 'unavailable'
        OR error_code IS DISTINCT FROM 'PROVIDER_REMOVED'
        OR last_error IS DISTINCT FROM 'Provider integration retired from OmniRoute v3.8.51'
        OR last_error_type IS DISTINCT FROM 'provider_removed'
        OR last_error_source IS DISTINCT FROM 'migration:retire-chatgpt-web'
        OR last_error_at IS NULL
      );

    UPDATE exclusive_connection_leases
    SET state = 'INVALIDATED',
        ended_at = to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
        end_reason = 'CONNECTION_INELIGIBLE'
    WHERE state = 'ACTIVE'
      AND connection_id = NEW.id;
RETURN NEW;
END;
$$;

