LANGUAGE plpgsql AS $$
BEGIN
  UPDATE free_proxies
    SET pool_proxy_id = NULL,
        in_pool = 0,
        updated_at = to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
    WHERE pool_proxy_id = OLD.id;
RETURN OLD;
END;
$$;

