--TRIGGER:request_detail_logs:trg_rdl_ring_buffer
CREATE OR REPLACE FUNCTION trg_rdl_ring_buffer_fn() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  DELETE FROM request_detail_logs
    WHERE id IN (
      SELECT id FROM request_detail_logs
      ORDER BY timestamp ASC
      LIMIT GREATEST(0, (SELECT COUNT(*) FROM request_detail_logs) - 500)
    );
RETURN NEW;
END;
$$;

CREATE OR REPLACE TRIGGER trg_rdl_ring_buffer
AFTER INSERT ON request_detail_logs FOR EACH ROW
EXECUTE FUNCTION trg_rdl_ring_buffer_fn();


